"use client"
import { useMorph } from "@/lib/sahajiv-motion/use-morph";
import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const AspectRatioVariants=cva("v-ratio [position:relative] [width:100%] [aspect-ratio:var(--ar,16/9)] [overflow:hidden] [border-radius:var(--r-card-sm)] [background:var(--card)] [display:grid] [place-items:center] [box-shadow:inset_0_0_0_1px_var(--v-border)] [color:var(--v-text-2)] [font-size:13px] [font-weight:500] [font-variant-numeric:tabular-nums]",{variants:{variant:{"default":"","pink":"-pink [background:var(--v-pink)] [--wm:var(--v-pink-deep)] [color:var(--v-on-accent)] [box-shadow:none]","yellow":"-yellow [background:var(--v-yellow)] [--wm:var(--v-yellow-deep)] [color:var(--v-on-accent)] [box-shadow:none]","blue":"-blue [background:var(--v-blue)] [--wm:var(--v-blue-deep)] [color:var(--v-on-accent)] [box-shadow:none]","olive":"-olive [background:var(--v-olive)] [--wm:var(--v-olive-deep)] [color:var(--v-on-accent)] [box-shadow:none]"},size:{"default":""}},defaultVariants:{variant:"default",size:"default"}})
export type AspectRatioProps=React.ComponentProps<"div"> & VariantProps<typeof AspectRatioVariants> & { ratio?:number }
export function AspectRatio({ref: externalMorphRef, className,variant,size,ratio=16/9,style,...props}:AspectRatioProps){const ownedMorphRef = useMorph<HTMLDivElement>("controls", externalMorphRef);
  const resolvedRatio=Number.isFinite(ratio)&&ratio>0?ratio:16/9;
  return <div ref={ownedMorphRef} data-slot="aspect-ratio" data-part="root" style={{"--ar":resolvedRatio,...style} as React.CSSProperties} className={cn(AspectRatioVariants({variant,size}),className)} {...props}/>}

@layer sahajiv-states {
/* Orthogonal authored class modifiers remain composable with CVA axes. */
.v-ratio[data-slot].-pink{background:var(--v-pink);--wm:var(--v-pink-deep);color:var(--v-on-accent);box-shadow:none}
.v-ratio[data-slot].-yellow{background:var(--v-yellow);--wm:var(--v-yellow-deep);color:var(--v-on-accent);box-shadow:none}
.v-ratio[data-slot].-blue{background:var(--v-blue);--wm:var(--v-blue-deep);color:var(--v-on-accent);box-shadow:none}
.v-ratio[data-slot].-olive{background:var(--v-olive);--wm:var(--v-olive-deep);color:var(--v-on-accent);box-shadow:none}

/* Authored contextual and pseudo-element rules, scoped to component-owned roots. */
.v-ratio[data-slot]>*{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.v-ratio[data-slot]>*{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.v-ratio[data-slot]>span{position:static;width:auto;height:auto;padding:0 12px;text-align:center}
.v-ratio[data-slot]>.v-wm{position:absolute;inset:auto;right:-10%;top:-16%;width:58%;height:auto;aspect-ratio:1;color:var(--wm,var(--v-beige-2));pointer-events:none}
.v-ratio[data-slot]:not([class*=" -"]){background:repeating-linear-gradient(135deg,transparent 0 6px,color-mix(in oklab,var(--v-edge) 45%,transparent) 6px 7px),var(--card);box-shadow:inset 0 0 0 1px var(--v-edge);color:var(--v-text)}
.v-ratio[data-slot]>img{position:absolute;inset:0}
.v-ratio[data-slot]>video{position:absolute;inset:0}
.v-ratio[data-slot]>iframe{position:absolute;inset:0}
:root[data-mode="dark"] .v-ratio[data-slot]:not([class*=" -"]){background:repeating-linear-gradient(135deg,transparent 0 6px,color-mix(in oklab,var(--v-text-2) 45%,transparent) 6px 7px),var(--v-beige)}


}
